func ValidateOrganizationEnterpriseIssuerKeyResponseBody(body *OrganizationEnterpriseIssuerKeyResponseBody) (err error) {
	if body.Kid == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("kid", "body"))
	}
	if body.State == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("state", "body"))
	}
	if body.State != nil {
		if !(*body.State == "pending" || *body.State == "active" || *body.State == "retired") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.state", *body.State, []any{"pending", "active", "retired"}))
		}
	}
	return
}

